def a(url, label, cls="button"):
    return f'<a class="{cls}" href="{escape(url, quote=True)}" target="_blank" rel="noopener noreferrer">{escape(label)} <span aria-hidden="true">↗</span></a>'

def shell(title, description, body, extra_script=""):
    return f'''<!doctype html><html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111727"><meta name="description" content="{escape(description, quote=True)}"><title>{escape(title)} · Proiectele lui Daniel</title><link rel="stylesheet" href="/style.css"></head><body><div class="site"><header class="topbar"><a href="/" class="brand"><span class="brand-mark">D<span>↗</span></span><span>PROIECTELE LUI<br><b>DANIEL</b></span></a><nav aria-label="Navigație"><a href="/">Toate proiectele</a><a href="https://github.com/DANIELluntras" target="_blank" rel="noopener noreferrer">GitHub ↗</a></nav></header>{body}<footer><span>Un catalog al proiectelor găsite pe acest calculator.</span><a href="https://github.com/DANIELluntras" target="_blank" rel="noopener noreferrer">DANIELluntras pe GitHub ↗</a></footer></div>{extra_script}</body></html>'''

cards = []
for i, p in enumerate(projects, 1):
    url = f'/proiecte/{p["slug"]}.html'
    cards.append(f'''<a class="card" href="{url}" data-category="{escape(p['category'])}" data-search="{escape((p['name']+' '+p['summary']+' '+p['category']).lower(), quote=True)}" style="--accent:{p['color']}"><span class="card-top"><span class="number">{i:02d} / {len(projects):02d}</span><span class="arrow">↗</span></span><span class="card-art"><span>{p['icon']}</span></span><span class="category">{escape(p['category'])}</span><strong>{escape(p['name'])}</strong><span class="card-summary">{escape(p['summary'])}</span><span class="card-bottom">VEZI PAGINA <span>→</span></span></a>''')

categories = ["Toate"] + list(dict.fromkeys(p['category'] for p in projects))
filters = ''.join(f'<button class="filter{ " active" if i == 0 else ""}" type="button" data-filter="{escape(c, quote=True)}">{escape(c)}</button>' for i,c in enumerate(categories))
home = f'''<main><section class="hero"><div class="eyebrow"><span class="live-dot"></span> ARHIVA PROIECTELOR · DANIELLUNTRAS</div><div class="hero-grid"><div><h1>Idei construite.<br><em>Proiecte explicate.</em></h1><p class="lead">O pagină pentru fiecare proiect din spațiul de lucru: ce face, cum este organizat și unde îl poți găsi.</p><a class="hero-cta" href="#proiecte">Explorează proiectele <span>↓</span></a></div><div class="hero-visual" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="hero-monogram">D</div><div class="visual-tag tag-one">CODE / CREATE</div><div class="visual-tag tag-two">{len(projects):02d} PROJECTS</div></div></div><div class="hero-meta"><span>WEB · JOCURI · BUSINESS · LIVE</span><span>SCROLL TO EXPLORE ↓</span></div></section><section id="proiecte" class="listing"><div class="section-head"><div><span class="eyebrow">01 / COLECȚIA</span><h2>Toate proiectele<span class="count">{len(projects):02d}</span></h2></div><p>Fiecare card deschide o pagină separată, cu o explicație clară și linkurile disponibile.</p></div><div class="controls"><div class="filters" role="group" aria-label="Filtrează proiectele">{filters}</div><label class="search">⌕ <input id="search" type="search" placeholder="Caută un proiect..." aria-label="Caută un proiect"></label></div><div class="grid" id="grid">{''.join(cards)}</div><p id="empty" class="empty" hidden>Nu am găsit proiecte pentru această căutare.</p></section></main>'''
(ROOT / 'index.html').write_text(shell('Acasă', 'Paginile proiectelor lui Daniel Luntras', home, '<script src="/app.js"></script>'), encoding='utf-8')

for index, p in enumerate(projects):
    previous = projects[index-1]
    following = projects[(index+1) % len(projects)]
    links = []
    if p['link']: links.append(a(p['link'], 'Deschide proiectul'))
    if p['github']: links.append(a(p['github'], 'Vezi codul pe GitHub', 'button secondary'))
    details = ''.join(f'<p>{escape(t)}</p>' for t in p['details'])
    features = ''.join(f'<li><span>✦</span>{escape(t)}</li>' for t in p['features'])
    actions = ''.join(links) if links else '<span class="unpublished">Nu există încă un link public confirmat pentru acest proiect.</span>'
    body = f'''<main><div class="detail-back"><a href="/">← Înapoi la toate proiectele</a><span>{index+1:02d} / {len(projects):02d}</span></div><section class="detail-hero" style="--accent:{p['color']}"><div class="detail-copy"><span class="eyebrow">{escape(p['category']).upper()} / PROIECT</span><h1>{escape(p['name'])}</h1><p>{escape(p['summary'])}</p><div class="actions">{actions}</div></div><div class="detail-art" aria-hidden="true"><div class="art-ring"></div><span>{p['icon']}</span></div></section><section class="detail-main"><div class="description"><span class="eyebrow">01 / DESPRE PROIECT</span><h2>Ce este și ce face</h2>{details}</div><aside class="facts"><span class="eyebrow">02 / PE SCURT</span><h3>Elemente principale</h3><ul>{features}</ul><div class="source"><span>FOLDER LOCAL</span><code>{escape(p['source'])}</code></div></aside></section><section class="next-project"><div><span class="eyebrow">MAI DEPARTE</span><h2>Continuă explorarea.</h2></div><a href="/proiecte/{following['slug']}.html">{escape(following['name'])} <span>↗</span></a></section></main>'''
    path = ROOT / 'proiecte' / (p['slug'] + '.html')
    path.parent.mkdir(exist_ok=True)
    path.write_text(shell(p['name'], p['summary'], body), encoding='utf-8')

(ROOT / '404.html').write_text(shell('Pagina nu există', 'Pagina căutată nu a fost găsită.', '<main class="missing"><span class="eyebrow">404</span><h1>Pagina nu a fost găsită.</h1><a class="button" href="/">Vezi proiectele →</a></main>'), encoding='utf-8')
print(f'Generated {len(projects)} project pages in {ROOT}')
